WITH lines AS (SELECT id, level, latency_ms, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS k, attr_value) SELECT id, level, latency_ms, k, attr_value, PERCENT_RANK() OVER (ORDER BY latency_ms) AS latency_ms_percent_rank, PERCENT_RANK() OVER (ORDER BY latency_ms NULLS LAST) AS latency_ms_percent_rank_2, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY level, k), 4) AS latency_ms_share, PERCENT_RANK() OVER (PARTITION BY k, level ORDER BY latency_ms DESC NULLS FIRST) AS latency_ms_percent_rank_3, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY k, level), 4) AS latency_ms_share_2 FROM lines;
